<?php
namespace App\Http\Controllers;
use App\Models\Account;use App\Services\ReportService;use Illuminate\Http\Request;
class ReportController {public function index(){return view('reports.index');}public function trial(Request $r){$d=$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from']);return view('reports.table',['title'=>'Trial Balance','rows'=>app(ReportService::class)->trialBalance($r->user()->company_id,$d['from'],$d['to'])]);}public function ledger(Request $r){$d=$r->validate(['account_id'=>'required|integer','from'=>'required|date','to'=>'required|date|after_or_equal:from']);Account::forCompany($r->user()->company_id)->findOrFail($d['account_id']);return view('reports.table',['title'=>'General Ledger','rows'=>app(ReportService::class)->generalLedger($r->user()->company_id,$d['account_id'],$d['from'],$d['to'])]);}public function pnl(Request $r){$d=$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from']);return view('reports.table',['title'=>'Profit & Loss','rows'=>app(ReportService::class)->profitAndLoss($r->user()->company_id,$d['from'],$d['to'])]);}public function balance(Request $r){$d=$r->validate(['as_of'=>'required|date']);return view('reports.table',['title'=>'Balance Sheet','rows'=>app(ReportService::class)->balanceSheet($r->user()->company_id,$d['as_of'])]);}public function ar(Request $r){$d=$r->validate(['as_of'=>'required|date']);return view('reports.table',['title'=>'AR Aging','rows'=>app(ReportService::class)->agingReceivable($r->user()->company_id,$d['as_of'])]);}public function ap(Request $r){$d=$r->validate(['as_of'=>'required|date']);return view('reports.table',['title'=>'AP Aging','rows'=>app(ReportService::class)->agingPayable($r->user()->company_id,$d['as_of'])]);}public function tax(Request $r){$d=$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from']);return view('reports.table',['title'=>'Tax Summary','rows'=>[app(ReportService::class)->taxSummary($r->user()->company_id,$d['from'],$d['to'])]]);}}
